class MyGrpcLikeLM(dspy.BaseLM):
    def __init__(self):
        super().__init__('grpc/internal', model_type='chat', temperature=0.0, max_tokens=1000, cache=False)
        self.stub = DummyLM([{'answer': 'offline ok'}])

    @property
    def supports_function_calling(self):
        return False

    @property
    def supports_reasoning(self):
        return False

    @property
    def supports_response_schema(self):
        return False

    @property
    def supported_params(self):
        return set()

    def forward(self, prompt=None, messages=None, **kwargs):
        if prompt == 'TOO LONG':
            raise dspy.ContextWindowExceededError(model=self.model)
        return self.stub.forward(prompt=prompt, messages=messages, **kwargs)

    async def aforward(self, prompt=None, messages=None, **kwargs):
        return self.forward(prompt=prompt, messages=messages, **kwargs)

